const roster=[{id:'retro',name:'РЕТРО',style:'Темп и быстрые серии',label:'Ретро'},{id:'sailor',name:'МОРЯК',style:'Стойкость и тяжёлые удары',label:'Моряк'},{id:'summer',name:'ДАЧНИК',style:'Сила и ближняя дистанция',label:'Дачник'}];let selected=0;const $=s=>document.querySelector(s),dialog=$('#dialog');function paint(){ $('#fighters').innerHTML=roster.map((x,i)=>`<button class="fighter ${i===selected?'selected':''}" data-index="${i}" aria-pressed="${i===selected}" aria-label="Выбрать: ${x.label}"><img src="../../art/portraits/generated-v1/${x.id}.png" alt="${x.label}"><span class="name">${x.name}</span><span class="style">${x.style}</span><span class="pick"></span></button>`).join('');$('#chosenName').textContent=roster[selected].label;$('#chosenStyle').textContent=roster[selected].style;document.querySelectorAll('.fighter').forEach(b=>b.onclick=()=>{selected=+b.dataset.index;paint()})}function show(html){$('#dialogContent').innerHTML=html;dialog.showModal()}$('#settings').onclick=()=>{show('<h2>Настройки</h2><div class="setting-row">Звук<input type="checkbox" checked aria-label="Звук"></div><div class="setting-row">Вибрация<input type="checkbox" checked aria-label="Вибрация"></div><div class="setting-row">Управление</div><div class="options"><button class="active">Свайпы</button><button>Кнопки</button><button>Вместе</button></div>');dialog.querySelectorAll('.options button').forEach(b=>b.onclick=()=>{dialog.querySelectorAll('.options button').forEach(x=>x.classList.toggle('active',x===b))})};$('#arenaTab').onclick=()=>{show('<h2>Арена</h2><div class="options"><button class="active">Переговорная</button><button>Двор</button><button>Кухня</button></div>');dialog.querySelectorAll('.options button').forEach(b=>b.onclick=()=>{dialog.querySelectorAll('.options button').forEach(x=>x.classList.toggle('active',x===b));$('#arenaTab').textContent=b.textContent})};$('#continue').onclick=()=>{let opponent=(selected+1)%3;show(`<h2>Соперник</h2><div class="duel"><div><img src="../../art/portraits/generated-v1/${roster[selected].id}.png" alt="${roster[selected].label}"><small>${roster[selected].label}</small></div><span>VS</span><div><img src="../../art/portraits/generated-v1/${roster[opponent].id}.png" alt="${roster[opponent].label}"><small>${roster[opponent].label}</small></div></div><div class="options" style="justify-content:flex-end;margin-top:12px">${roster.filter((_,i)=>i!==selected).map(x=>`<button data-opponent="${x.id}">${x.label}</button>`).join('')}</div>`);dialog.querySelectorAll('[data-opponent]').forEach(b=>b.onclick=()=>{const x=roster.find(x=>x.id===b.dataset.opponent);const div=dialog.querySelector('.duel>div:last-child');div.innerHTML=`<img src="../../art/portraits/generated-v1/${x.id}.png" alt="${x.label}"><small>${x.label}</small>`})};$('#back').onclick=()=>{if(dialog.open)dialog.close();else {selected=0;paint()}};$('#rosterTab').onclick=()=>{if(dialog.open)dialog.close()};paint();
